  const num = (v, a, b) => Math.max(a, Math.min(b, Number(v) || 0));
  const ex = (Array.isArray(x.ex) ? x.ex : []).slice(0, 25).map((e, i) => ({
    id: String(e.id || 'e' + i).slice(0, 40), name: String(e.name || '').slice(0, 60), rest: Math.round(num(e.rest, 0, 900)),
    sets: (Array.isArray(e.sets) ? e.sets : []).slice(0, 20).map(s => ({ kg: Math.round(num(s.kg, 0, 500) * 4) / 4, reps: Math.round(num(s.reps, 0, 200)), done: !!s.done, t: Math.round(num(s.t, 0, 9e15)) })),
  })).filter(e => e.name);
